<script setup>
import { computed,onMounted,ref,watch } from 'vue';
import { useContext } from '../composables/context.js';
import { api } from '../services/accounting.js';
import { documentError } from '../services/invoice-documents.js';
import { calculateInvoice,splitInstallments } from '../../../shared/invoice-money.js';
import { cents } from '../../../shared/money.js';
import { reportMoney as money } from '../services/report-format.js';
import { t,treasuryError } from '../locales/treasury.js';
import FormDialog from './FormDialog.vue';
import PartyProfileFields from './PartyProfileFields.vue';
import {emptyPartyProfile,completeFiscalProfile} from '../../../shared/account-party.js';
import {partyText} from '../locales/parties.js';
import {partyPaymentReceipts,emptyPartyPaymentProfile} from '../../../shared/party-payments.js';
import {partyPaymentText as pay} from '../locales/party-payments.js';
import PartyPaymentSummary from './PartyPaymentSummary.vue';
const props=defineProps({direction:String,initialValue:Object,documentId:[String,Number],documentVersion:Number}),emit=defineEmits(['close','saved']);
const {company,selectedExercise}=useContext();
const busy=ref(false),loading=ref(true),error=ref(''),accounts=ref([]),parties=ref([]),partySearch=ref(''),numbering=ref(null),numberLoading=ref(false);
const logoFailed=ref(false);
const autoReference=ref(props.direction==='issued'&&!props.documentId&&!props.initialValue?.reference);
const now=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid'}).format(new Date()),period=selectedExercise.value;
const initial=now>=period.start_date&&now<=period.end_date?now:period.start_date;
function addDays(value,days){const day=new Date(value+'T00:00:00Z');if(!Number.isFinite(day.getTime()))return value;day.setUTCDate(day.getUTCDate()+days);return day.toISOString().slice(0,10);}
const form=ref({exercise_id:period.id,direction:props.direction,reference:'',invoice_date:initial,posting_date:initial,party:{name:'',tax_id:'',address:'',email:''},party_account_id:'',party_parent:props.direction==='issued'?'4300':'4000',offset_account_id:'',vat_account_id:'',withholding_account_id:'',withholding_rate:'0',payment_method:company.value.payment_method || 'transfer',notes:'',lines:[{description:'',base:'',tax_rate:'21'}],receipts:[{due_date:addDays(initial,30),amount:'0.00'}],request_id:crypto.randomUUID()});
if(props.initialValue)form.value=JSON.parse(JSON.stringify(props.initialValue));
form.value.party={...emptyPartyProfile(),...form.value.party};
form.value.automatic_receipts=props.initialValue?.automatic_receipts??!props.documentId;
const schedule=ref({count:form.value.receipts.length,first:form.value.receipts[0]?.due_date||addDays(initial,30),months:1});
const calculationState=computed(()=>{try{return {totals:calculateInvoice(form.value.lines,form.value.withholding_rate)};}catch(cause){return {totals:null,error:treasuryError(cause)};}});
const calculation=computed(()=>calculationState.value.totals);
const scheduleValid=computed(()=>{try{return !!calculation.value&&form.value.receipts.length>0&&form.value.receipts.every(row=>cents(row.amount)>0n&&row.due_date>=form.value.invoice_date)&&form.value.receipts.reduce((sum,row)=>sum+cents(row.amount),0n)===cents(calculation.value.total_amount);}catch{return false;}});
const partyAccounts=computed(()=>accounts.value.filter(row=>(props.direction==='issued'?['430','440']:['400','410']).some(prefix=>row.code.startsWith(prefix))));
const normalizeSearch=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').replaceAll('.','');
const selectedPartyAccount=computed(()=>partyAccounts.value.find(row=>String(row.id)===String(form.value.party_account_id)));
const automaticSchedule=computed(()=>{if(!calculation.value)return {rows:[],error:''};try{return {rows:partyPaymentReceipts(calculation.value.total_amount,form.value.invoice_date,selectedPartyAccount.value?.payment_profile),error:''};}catch(cause){return {rows:[],error:treasuryError(cause)};}});
watch([()=>form.value.automatic_receipts,automaticSchedule],([automatic,result],previous)=>{if(automatic){form.value.receipts=result.rows;form.value.payment_profile={...emptyPartyPaymentProfile(),...selectedPartyAccount.value?.payment_profile};}else if(previous?.[0]){schedule.value.count=form.value.receipts.length||1;schedule.value.first=form.value.receipts[0]?.due_date||addDays(form.value.invoice_date,30);schedule.value.months=selectedPartyAccount.value?.payment_profile?.interval_months||1;}}, {immediate:true});
const filteredPartyAccounts=computed(()=>{const terms=normalizeSearch(partySearch.value).trim().split(/\s+/).filter(Boolean);return partyAccounts.value.filter(account=>{const known=parties.value.find(row=>String(row.account_id)===String(account.id)&&row.direction===props.direction);const value=normalizeSearch([account.code,account.description,known?.name,known?.tax_id].join(' '));return terms.every(term=>value.includes(term));});});
const selectedOutsideSearch=computed(()=>selectedPartyAccount.value&&!filteredPartyAccounts.value.some(row=>row.id===selectedPartyAccount.value.id));
function matching(prefixes){return accounts.value.filter(row=>prefixes.some(prefix=>row.code.startsWith(prefix)));}
watch(()=>calculation.value?.total_amount,total=>{if(total&&!form.value.automatic_receipts&&form.value.receipts.length===1)form.value.receipts[0].amount=total;});
watch(()=>form.value.invoice_date,(value,old)=>{if(form.value.posting_date===old)form.value.posting_date=value;if(!form.value.automatic_receipts){schedule.value.first=addDays(value,30);if(form.value.receipts.length===1)form.value.receipts[0].due_date=schedule.value.first;}});
function applyNumber(data){numbering.value=data;if(data.automatic_available&&autoReference.value)form.value.reference=data.reference;else if(!data.automatic_available)autoReference.value=false;}
async function nextNumber(){if(numberLoading.value||busy.value)return;numberLoading.value=true;try{const data=await api('/invoices/next-reference?exercise_id='+period.id);autoReference.value=true;applyNumber(data);}catch(cause){autoReference.value=false;error.value=treasuryError(cause);}finally{numberLoading.value=false;}}
onMounted(async()=>{const results=await Promise.allSettled([api('/accounts?kind=subaccount'),api('/invoices/parties'),autoReference.value?api('/invoices/next-reference?exercise_id='+period.id):Promise.resolve(null)]);for(const [index,result]of results.entries()){if(result.status==='rejected'){error.value=treasuryError(result.reason);if(index===2)autoReference.value=false;}else if(index===0)accounts.value=result.value;else if(index===1)parties.value=result.value;else if(result.value)applyNumber(result.value);}if(selectedPartyAccount.value?.party_profile)form.value.party=completeFiscalProfile(form.value.party,selectedPartyAccount.value.party_profile);loading.value=false;});
function chooseParty(){partySearch.value='';const known=parties.value.find(row=>String(row.account_id)===String(form.value.party_account_id)&&row.direction===props.direction),account=partyAccounts.value.find(row=>String(row.id)===String(form.value.party_account_id));form.value.party={...emptyPartyProfile(),name:account?.description||'',...Object.fromEntries(Object.keys(emptyPartyProfile()).filter(key=>known&&Object.hasOwn(known,key)).map(key=>[key,known[key]])),...account?.party_profile};form.value.payment_method=account?.payment_profile?.payment_method||company.value.payment_method||'transfer';form.value.automatic_receipts=true;}
function distribute(){try{if(!calculation.value)throw {code:'INVALID_INVOICE_AMOUNT'};form.value.receipts=splitInstallments(calculation.value.total_amount,Number(schedule.value.count),schedule.value.first,Number(schedule.value.months));error.value='';}catch(cause){error.value=treasuryError(cause);}}
function addReceipt(){const last=form.value.receipts.at(-1);form.value.receipts.push({due_date:last?addDays(last.due_date,30):schedule.value.first,amount:'0.00'});}
async function save(){if(busy.value||numberLoading.value)return;error.value='';if(!scheduleValid.value){error.value=t.scheduleMismatch;return;}busy.value=true;try{const result=props.documentId?await api('/invoice-documents/'+props.documentId,{method:'PATCH',body:{version:props.documentVersion,form:form.value}}):await api('/invoices',{method:'POST',body:{...form.value,...(props.direction==='issued'?{auto_reference:autoReference.value}:{})}});emit('saved',result);}catch(cause){error.value=props.documentId?documentError(cause):treasuryError(cause);}finally{busy.value=false;}}
</script>
<template>
 <FormDialog class="invoice-form-dialog" :title="documentId?'Editar propuesta':direction==='issued'?t.newIssued:t.newReceived" :busy="busy" @close="emit('close')">
  <p v-if="loading" role="status">{{ t.loading }}</p><p v-if="error" class="notice error-notice" role="alert">{{ error }}</p>
  <form v-if="!loading" @submit.prevent="save"><fieldset :disabled="busy">
   <section class="trade-form-section"><div class="invoice-company-heading"><img v-if="direction==='issued'&&company.logo_url&&!logoFailed" class="invoice-form-logo" :src="company.logo_url" :alt="'Anagrama de '+company.name" @error="logoFailed=true"><h3>{{ t.invoices }} · {{ company.name }} · {{ period.name }}</h3></div><div class="form-grid">
    <div class="invoice-reference-field"><label>{{ t.reference }}<input v-model="form.reference" name="invoice_reference" maxlength="60" :disabled="numberLoading" required autofocus @input="autoReference=false"></label><template v-if="direction==='issued'&&!documentId"><small class="muted">{{ autoReference?t.autoReferenceHelp:t.manualReferenceHelp }}</small><small v-if="numbering?.previous" class="trade-cell-note">{{ t.lastReference }}: {{ numbering.previous.reference }} · {{ numbering.previous.source==='invoice'?t.invoiceSource:t.journalSource }}</small><small v-else-if="numbering" class="trade-cell-note">{{ t.firstReference }}</small><button type="button" class="button invoice-next-reference" :disabled="busy||numberLoading" @click="nextNumber">{{ numberLoading?t.numberingLoading:t.autoReference }}</button></template></div><label>{{ t.paymentMethod }}<select v-model="form.payment_method" name="payment_method"><option v-for="(label,key) in t.methods" :key="key" :value="key">{{ label }}</option></select></label>
    <label>{{ t.invoiceDate }}<input v-model="form.invoice_date" name="invoice_date" type="date" min="1000-01-01" :max="form.posting_date" required></label><label>{{ t.postingDate }}<input v-model="form.posting_date" name="posting_date" type="date" :min="period.start_date" :max="period.end_date" required></label>
   </div><p v-for="warning in numbering?.warnings||[]" :key="warning" class="notice">{{ warning }}</p></section>
   <section class="trade-form-section"><h3>{{ t.party }}</h3><p class="muted">{{ t.partyHelp }}</p><label>{{ t.partyAccountSearch }}<input v-model="partySearch" name="party_account_search" type="search" maxlength="200" :placeholder="t.partyAccountSearchHint" autocomplete="off" @keydown.enter.prevent></label><label>{{ t.partyAccount }}<select v-model="form.party_account_id" name="party_account_id" @change="chooseParty"><option value="">{{ t.newParty }}</option><option v-if="selectedOutsideSearch" :value="selectedPartyAccount.id">{{ selectedPartyAccount.code }} · {{ selectedPartyAccount.description }} · {{ t.selectedAccount }}</option><option v-for="account in filteredPartyAccounts" :key="account.id" :value="account.id">{{ account.code }} · {{ account.description }}</option></select></label><p v-if="partySearch" class="muted" role="status">{{ filteredPartyAccounts.length?filteredPartyAccounts.length+' '+t.matchingAccounts:t.noPartyAccounts }}</p>
    <p v-if="selectedPartyAccount?.party_profile" class="muted">{{ partyText.invoiceHelp }}</p><PartyProfileFields v-model="form.party" />
    <label v-if="!form.party_account_id">{{ t.partyParent }}<select v-model="form.party_parent" name="party_parent"><template v-if="direction==='issued'"><option value="4300">4300 · {{ t.customer }}</option><option value="4400">4400 · {{ t.debtor }}</option></template><template v-else><option value="4000">4000 · {{ t.supplier }}</option><option value="4100">4100 · {{ t.creditor }}</option></template></select></label>
   </section>
   <section class="trade-form-section"><h3>{{ t.items }}</h3><div class="table-wrap"><table class="invoice-lines-form"><thead><tr><th>{{ t.concept }}</th><th>{{ t.base }}</th><th>{{ t.vatRate }}</th><th>{{ t.remove }}</th></tr></thead><tbody><tr v-for="(line,index) in form.lines" :key="index"><td><input v-model="line.description" :name="'line_description_'+index" :aria-label="t.concept+' '+(index+1)" maxlength="200" required></td><td><input v-model="line.base" :name="'line_base_'+index" :aria-label="t.base+' '+(index+1)" inputmode="decimal" required></td><td><input v-model="line.tax_rate" :name="'line_tax_'+index" :aria-label="t.vatRate+' '+(index+1)" inputmode="decimal" required></td><td><button v-if="form.lines.length>1" type="button" class="button" @click="form.lines.splice(index,1)">{{ t.remove }}</button></td></tr></tbody></table></div><button type="button" class="button" :disabled="form.lines.length>=40" @click="form.lines.push({description:'',base:'',tax_rate:'21'})">{{ t.addLine }}</button>
    <label class="retention-field">{{ t.withholdingRate }}<input v-model="form.withholding_rate" name="withholding_rate" inputmode="decimal" required></label>
    <div v-if="calculation" class="trade-totals" aria-live="polite"><span v-for="[key,label] in [['base_total',t.base],['tax_total',t.vat],['withholding_total',t.withholding],['total_amount',t.total]]" :key="key">{{ label }}<strong>{{ money(calculation[key]) }} €</strong></span></div><p v-else-if="form.lines.some(line=>line.base)" class="notice error-notice" role="alert">{{ calculationState.error }}</p>
    <details class="trade-account-settings" :open="!!documentId"><summary>{{ t.accounting }}</summary><div class="form-grid"><label>{{ t.offset }}<select v-model="form.offset_account_id" name="offset_account_id" :required="!!documentId"><option value="">{{ documentId?'Selecciona la cuenta de gasto o ingreso':t.automatic+' · '+(direction==='issued'?'7000':'6000') }}</option><option v-for="account in matching(direction==='issued'?['7']:['6','2'])" :key="account.id" :value="account.id">{{ account.code }} · {{ account.description }}</option></select></label><label>{{ t.vatAccount }}<select v-model="form.vat_account_id"><option value="">{{ t.automatic }} · {{ direction==='issued'?'4770':'4720' }}</option><option v-for="account in matching(direction==='issued'?['477']:['472'])" :key="account.id" :value="account.id">{{ account.code }} · {{ account.description }}</option></select></label><label>{{ t.withholdingAccount }}<select v-model="form.withholding_account_id"><option value="">{{ t.automatic }} · {{ direction==='issued'?'4730':'4751' }}</option><option v-for="account in matching(direction==='issued'?['473']:['4751'])" :key="account.id" :value="account.id">{{ account.code }} · {{ account.description }}</option></select></label></div></details>
   </section>
   <section class="trade-form-section"><h3>{{ t.receipts }}</h3><label class="automatic-receipts"><input v-model="form.automatic_receipts" name="automatic_receipts" type="checkbox">{{ pay.automatic }}</label><p class="muted">{{ pay.automaticHelp }}</p><PartyPaymentSummary v-if="form.automatic_receipts" :profile="selectedPartyAccount?.payment_profile" /><p v-if="form.automatic_receipts&&automaticSchedule.error" class="notice error-notice" role="alert">{{ automaticSchedule.error }}</p><template v-if="!form.automatic_receipts"><p class="muted">{{ t.scheduleHelp }}</p><div class="receipt-distribution"><label>{{ t.numberReceipts }}<input v-model="schedule.count" name="receipt_count" type="number" min="1" max="60"></label><label>{{ t.firstDue }}<input v-model="schedule.first" name="first_due" type="date" :min="form.invoice_date" max="9999-12-31"></label><label>{{ t.every }}<select v-model="schedule.months"><option v-for="value in [1,2,3,6,12]" :key="value" :value="value">{{ value }}</option></select></label><button type="button" class="button" :disabled="!calculation" @click="distribute">{{ t.distribute }}</button></div></template>
    <div class="table-wrap"><table class="invoice-receipts-form"><thead><tr><th>{{ t.receipt }}</th><th>{{ t.dueDate }}</th><th>{{ t.amount }}</th><th v-if="!form.automatic_receipts">{{ t.remove }}</th></tr></thead><tbody><tr v-for="(row,index) in form.receipts" :key="index"><td>{{ index+1 }}</td><td><input v-model="row.due_date" :readonly="form.automatic_receipts" :name="'due_date_'+index" :aria-label="t.dueDate+' '+(index+1)" type="date" :min="form.invoice_date" max="9999-12-31" required></td><td><input v-model="row.amount" :readonly="form.automatic_receipts" :name="'due_amount_'+index" :aria-label="t.amount+' '+(index+1)" inputmode="decimal" required></td><td v-if="!form.automatic_receipts"><button v-if="form.receipts.length>1" type="button" class="button" @click="form.receipts.splice(index,1)">{{ t.remove }}</button></td></tr></tbody></table></div>
    <button v-if="!form.automatic_receipts" type="button" class="button" :disabled="form.receipts.length>=60" @click="addReceipt">{{ t.addReceipt }}</button><p v-if="calculation&&!scheduleValid" class="notice" role="status">{{ t.scheduleMismatch }}</p>
   </section><label>{{ t.notes }}<textarea v-model="form.notes" name="invoice_notes" maxlength="1000" rows="3"></textarea></label>
  </fieldset><div class="actions trade-form-actions"><button class="button primary" :disabled="busy||numberLoading||!calculation||!scheduleValid">{{ documentId?'Guardar propuesta':t.saveInvoice }}</button><button type="button" class="button" :disabled="busy" @click="emit('close')">{{ t.cancel }}</button></div></form>
 </FormDialog>
</template>
<style scoped>.automatic-receipts{display:flex;flex-direction:row;align-items:flex-start;gap:10px;margin:14px 0}.automatic-receipts input{width:auto;min-height:0;margin-top:3px;flex-shrink:0}</style>
